package com.vandorlabs.neoforge.programmer;
import com.vandorlabs.neoforge.client.NativeProgrammerScreen;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import com.vandorlabs.neoforge.screen.NativeChipJournal;
import com.vandorlabs.programmer.ProgrammerStatus;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.ItemStack;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
/** Actual title-only widgets and container rendering; no world, gameplay or canonical-registration claims. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class ProgrammerScreenChecks {
 private static NativeProgrammerScreen screen;private static NativeProgrammerMenu menu;
 private static final List<ProgrammerSettingsPayload> edits=new ArrayList<>();
 private static int stage,ticks,checks,size,hover,frames;private static boolean captured;private static String capture;
 private static CompletableFuture<Void> reload;
 private static final int[][] SIZES={{320,240},{400,300},{640,360}};
 private static boolean enabled(){return Boolean.getBoolean("vandorlabs.programmerScreenCheck");}
 @EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)public static final class Registration{
  @SubscribeEvent public static void screens(RegisterMenuScreensEvent event){if(enabled())NativeProgrammerScreen.register(event,ProgrammerHostChecks.menuType());}
  @SubscribeEvent public static void reload(RegisterClientReloadListenersEvent event){if(enabled())NativeProgrammerScreen.registerReload(event);}
 }
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Programmer screen stage="+stage+" size="+size+": "+why);}
 private static void click(int id,int button){var widget=screen.button(id);need(widget!=null&&widget.visible&&widget.active,"available widget "+id);need(screen.mouseClicked(widget.getX()+widget.getWidth()/2D,widget.getY()+widget.getHeight()/2D,button),"actual widget click "+id);}
 private static ItemStack journal(){var chip=NativeCredentialItems.dataChip(2);NativeChipJournal.write(chip,true,"Fixture",new String[8]);return chip;}
 private static void create(Minecraft mc){var tile=new NativeProgrammerEntity(ProgrammerHostChecks.entityType(),BlockPos.ZERO,ProgrammerHostChecks.block().defaultBlockState());var projection=new CompoundTag();projection.putBoolean("ProgrammerProjection",true);projection.putInt("ProgrammerProjectionVersion",1);projection.putInt("Status",ProgrammerStatus.READY.ordinal());projection.putLong("Sequence",1);projection.putIntArray("Kinds",new int[]{0,2,0});projection.putIntArray("Companies",new int[]{-1,2,-1});var draft=new NativeProgrammerDraft(false,true,"Fixture",List.of("","Long journal line\n".repeat(30),"","","","","",""));var text=new CompoundTag();draft.write(text);projection.put("Draft",text);tile.loadWithComponents(projection,RegistryAccess.EMPTY);menu=new NativeProgrammerMenu(ProgrammerHostChecks.menuType(),37,new Inventory(null),tile);menu.contents().setItem(1,journal());need(menu.contents()!=tile&&tile.getItem(1).isEmpty(),"client shadow cannot become physical service");edits.clear();screen=new NativeProgrammerScreen(menu,new Inventory(null),Component.literal("Card / Chip Programmer"),edits::add);screen.init(mc,SIZES[size][0],SIZES[size][1]);need(screen.journalPage()&&screen.visibleLines()==(size==0?4:8),"source journal auto-tab and compact/tall line count");for(int id:new int[]{0,1,2,4,5,6,7,8}){var button=screen.button(id);need(button.getX()>=screen.getGuiLeft()&&button.getX()+button.getWidth()<=screen.getGuiLeft()+252&&button.getY()>=screen.getGuiTop()&&button.getY()+button.getHeight()<=screen.getGuiTop()+screen.getYSize(),"widget bounds "+id);}click(0,1);need(!screen.editingDraft().journal()&&!screen.journalPage(),"reverse Type selects previous available nonVehicle Master");click(0,0);click(6,0);need(screen.editingDraft().journal()&&screen.journalPage(),"forward Type and Journal tab");double x=screen.getGuiLeft()+25,y=screen.getGuiTop()+135;need(screen.mouseClicked(x,y,0)&&screen.editing(),"actual journal paper focus");screen.charTyped('A',0);screen.charTyped('Ω',0);screen.keyPressed(257,0,0);screen.charTyped('B',0);screen.keyPressed(259,0,0);need(screen.editingDraft().pages().getFirst().equals("AΩ\n"),"keyboard Unicode/newline/backspace");screen.keyPressed(65,0,2);screen.keyPressed(261,0,0);need(screen.editingDraft().pages().getFirst().isEmpty(),"actual Ctrl+A/delete");screen.insert("Local draft");edits.clear();for(int i=0;i<9;i++)screen.advanceEditor();need(edits.size()==1&&edits.getFirst().operation()==0&&edits.getFirst().window()==37,"nine-observation bounded autosave");for(int i=0;i<20;i++)screen.advanceEditor();need(edits.size()==1,"unchanged draft does not resend");screen.titleField().setValue("Local pending title");menu.contents().setItem(2,journal());screen.advanceEditor();int sent=edits.size();click(8,0);need(edits.size()==sent+1&&edits.getLast().operation()==2&&edits.getLast().draft().equals(NativeProgrammerDraft.empty())&&screen.editingDraft().title().equals("Local pending title"),"Copy dispatch is separate and keeps pending draft");menu.contents().setItem(2,journal());screen.advanceEditor();need(screen.editingDraft().pages().getFirst().equals("Local draft")&&screen.editingDraft().title().equals("Local pending title"),"output update does not reload local draft");click(2,0);need(screen.page()==1&&screen.maxScroll()>0,"next page loads scrollable text");int before=screen.scroll();need(screen.mouseScrolled(x,y,0,-1)&&screen.scroll()>before,"actual journal wheel");need(screen.mouseClicked(screen.getGuiLeft()+233,screen.getGuiTop()+screen.paperBottom()-1,0),"scrollbar press");int end=screen.scroll();need(screen.mouseDragged(screen.getGuiLeft()+233,screen.getGuiTop()+126,0,0,-100)&&screen.scroll()<end,"actual scrollbar drag");screen.mouseReleased(0,0,0);click(5,0);need(menu.slots.stream().allMatch(slot->slot.isActive()),"all inventory slots visible on Inventory");hover=0;frames=0;}
 private static void capture(String name){capture=name;captured=false;frames=0;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!enabled()||stage==9)return;var mc=Minecraft.getInstance();try{if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}need(++ticks<2600,"title timeout");if(ticks<80||mc.getOverlay()!=null||!(mc.screen instanceof TitleScreen))return;need(mc.level==null&&mc.getSingleplayerServer()==null,"no server/world");switch(stage){case 0->{mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();create(mc);stage=1;}case 1->{if(frames<2)return;need(screen.getSlotUnderMouse()==menu.slots.get(hover),"actual rendered slot hit "+hover);frames=0;if(++hover==39){capture("programmer-inventory-"+size+".png");stage=2;}}case 2->{if(!captured)return;click(6,0);capture("programmer-journal-"+size+".png");stage=3;}case 3->{if(!captured)return;need(menu.slots.subList(3,39).stream().noneMatch(slot->slot.isActive())&&screen.getSlotUnderMouse()==null,"journal hides player slots and paper has no inventory hit");if(++size<SIZES.length){create(mc);stage=1;}else{reload=mc.reloadResourcePacks();stage=4;}}case 4->{if(!reload.isDone())return;reload.join();screen.init(mc,640,360);need(screen.editingDraft().title().equals("Local pending title")&&screen.page()==1,"reload/resize retain local draft and page");capture("programmer-reloaded.png");stage=5;}case 5->{if(!captured)return;System.out.println("[vandorlabs][programmer-screen] title PASS checks="+checks+" sizes=3 actual39slotHits keyboard reverseType scrollbar debounce Copy resize reload clientShadow noWorld");stage=9;mc.stop();}}}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][programmer-screen] FAIL "+failure);stage=9;mc.stop();}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||screen==null||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var graphics=event.getGuiGraphics();double x=screen.getGuiLeft()+25,y=screen.getGuiTop()+135;if(stage==1&&hover<39){var slot=menu.slots.get(hover);x=screen.getGuiLeft()+slot.x+8;y=screen.getGuiTop()+slot.y+8;}graphics.flush();graphics.pose().pushPose();try{graphics.pose().translate(0,0,300);graphics.fill(0,0,Minecraft.getInstance().getWindow().getGuiScaledWidth(),Minecraft.getInstance().getWindow().getGuiScaledHeight(),0xFF101012);screen.render(graphics,(int)x,(int)y,0);graphics.flush();frames++;}finally{graphics.pose().popPose();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!enabled()||capture==null||frames<6)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->{captured=true;});}
}
